function showSavedAnalyses(review){
  const box=$('saved-analysis-summary');box.replaceChildren();if(!review)return;
  const config=review.config,enabled=config.analysis!=='cna',counts={marlin:0,sturgeon:0,skip:0};
  for(const sample of review.samples){const model=sample.methylation_classifier;if(model==='marlin'||model==='sturgeon')counts[model]++;else counts.skip++;}
  box.append(node('h3','Analyses selected for this run'));
  for(const text of ['CNA: '+(config.analysis==='methylation'?'Off':'Enabled'),
    'Small variants: '+(config.run_variants?'Enabled':'Off'),
    'Methylation: '+(enabled?'Enabled — MARLIN '+counts.marlin+', Sturgeon '+counts.sturgeon+', skipped '+counts.skip:'Off')])box.append(node('p',text));
  if(enabled){const table=node('table'),header=node('tr');for(const label of ['Sample','Methylation classifier'])header.append(node('th',label));table.append(header);
    for(const sample of review.samples){const row=node('tr'),model=sample.methylation_classifier;row.append(node('td',sample.name),node('td',model==='marlin'?'MARLIN':model==='sturgeon'?'Sturgeon':'Skip methylation'));table.append(row);}box.append(table);}
}

